"""Initialize explicit SE workspace without overwriting existing identity files."""
import argparse
import json
import os
from pathlib import Path
import stat

BEGIN = '<!-- seagent-project-init:begin -->'
END = '<!-- seagent-project-init:end -->'
# Exact legacy block generated by this plugin; only this old form is migrated.
LEGACY_BLOCK = BEGIN + '\n请在当前聊天显式读取同目录 `SE-SOUL.md` 全文，并遵循其中的 SE 行为原则。文件存在不代表已经加载。\n' + END


def regular_text(path):
    if not stat.S_ISREG(path.lstat().st_mode):
        raise ValueError(f'{path.name}: 必须为非空普通文件，保留现有路径')
    text = path.read_bytes().decode('utf-8')
    if not text.strip():
        raise ValueError(f'{path.name}: 空文件，保留并等待用户处理')
    return text


def initialize(workspace):
    if not workspace.is_absolute():
        raise ValueError('workspace 必须是明确的绝对路径')
    if not workspace.is_dir():
        raise ValueError('workspace 必须是已存在的目录')
    workspace = workspace.resolve()
    if os.path.lexists(workspace / 'AGENTS.override.md'):
        raise ValueError('AGENTS.override.md: 可能遮蔽 AGENTS.md，保留并等待用户处理，初始化未完成')
    soul, agents = workspace / 'SE-SOUL.md', workspace / 'AGENTS.md'
    # Preflight both paths before any mutation, including dangling links via lexists.
    soul_exists, agents_exists = os.path.lexists(soul), os.path.lexists(agents)
    template = Path(__file__).resolve().parents[1] / 'assets/SE-SOUL.md'
    soul_text = regular_text(soul if soul_exists else template)
    block = BEGIN + '\n' + soul_text + ('' if soul_text.endswith('\n') else '\n') + END
    replacement = None
    action = None
    if agents_exists:
        if agents.is_symlink():
            target = Path(os.readlink(agents))
            if not target.is_absolute():
                target = workspace / target
            if not soul_exists or target.resolve() != soul:
                raise ValueError('AGENTS.md: 未知链接或断链，保留且不跟随修改')
        else:
            text = regular_text(agents)
            if BEGIN in text or END in text:
                if text.count(BEGIN) != 1 or text.count(END) != 1:
                    raise ValueError('AGENTS.md: 初始化标记冲突，保留原文')
                if block in text:
                    pass
                elif LEGACY_BLOCK in text:
                    replacement = text.replace(LEGACY_BLOCK, block)
                    action = 'migrated exact legacy reference block to SE-SOUL body'
                else:
                    raise ValueError('AGENTS.md: 未知或与当前 SOUL 不一致的标记块，保留原文')
            else:
                replacement = text + '\n\n' + block + '\n'
                action = 'appended marked SE-SOUL body to AGENTS.md'
    actions = []
    if not soul_exists:
        with soul.open('xb') as handle:
            handle.write(soul_text.encode('utf-8'))
        actions.append('created SE-SOUL.md from template')
    if not agents_exists:
        agents.symlink_to('SE-SOUL.md')
        actions.append('created relative AGENTS.md -> SE-SOUL.md')
    elif replacement is not None:
        # Refuse symlink substitution and changed contents; preserve user prefix/suffix bytes.
        fd = os.open(agents, os.O_RDWR | os.O_NOFOLLOW)
        with os.fdopen(fd, 'r+b') as handle:
            if handle.read() != text.encode('utf-8'):
                raise ValueError('AGENTS.md: 写入前内容发生变化，保留当前文件')
            handle.seek(0)
            handle.write(replacement.encode('utf-8'))
            handle.truncate()
        actions.append(action)
    return {'status': 'configured', 'workspace': str(workspace), 'actions': actions,
            'identity_loaded': False, 'read_next': [str(agents), str(soul)],
            'session_scope': 'Initialized project only; subject to Codex directory scope, overrides and instruction size budget'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--workspace', required=True, type=Path)
    args = parser.parse_args()
    try:
        result = initialize(args.workspace)
    except (ValueError, OSError, UnicodeError) as exc:
        print(json.dumps({'status': 'conflict', 'error': str(exc)}, ensure_ascii=False))
        return 1
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
